INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('811e192f-9cb4-480b-a073-db2765d9dd6c','9','geografie-fizica','published',1,81,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('811e192f-9cb4-480b-a073-db2765d9dd6c','ro','De ce este imposibil să reprezinți suprafața curbă a Pământului pe o hartă plană fără nicio deformare?','["Pentru că Pământul este prea mare pentru orice foaie de hârtie.","Pentru că o suprafață curbă nu poate fi întinsă pe un plan fără a fi deformată.","Pentru că meridianele și paralele sunt invizibile.","Pentru că hârtia nu poate reda culorile reliefului."]','Încearcă mental să întinzi coaja unei portocale pe masă, perfect neted — nu se poate fără să o rupi sau să o întinzi. La fel, trecerea de la curb la plan cere obligatoriu o deformare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('4b605b5f-3335-4191-ab3f-0da7d6dcd62a','9','geografie-fizica','published',2,82,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('4b605b5f-3335-4191-ab3f-0da7d6dcd62a','ro','Pe o hartă în proiecție cilindrică (Mercator), Groenlanda pare aproape cât Africa, deși în realitate este de câteva ori mai mică. Cum se explică?','["Groenlanda chiar are aceeași suprafață ca Africa.","Groenlanda pare mare pentru că este acoperită de gheață.","Proiecția cilindrică mărește tot mai mult suprafețele pe măsură ce ne apropiem de poli.","Groenlanda este, de fapt, situată lângă Ecuator."]','Amintește-ți unde este fidelă proiecția cilindrică și unde deformează cel mai mult. Fiind exactă la Ecuator și tot mai deformată spre poli, ea umflă suprafețele din apropierea polilor — de aceea Groenlanda apare uriașă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9bf73ceb-edbe-4f48-9fa7-9734a68a6c34','9','geografie-fizica','published',0,83,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9bf73ceb-edbe-4f48-9fa7-9734a68a6c34','ro','Care proiecție este cea mai potrivită pentru a reprezenta corect o regiune polară?','["Proiecția azimutală (plană), pentru că planul este așezat tangent chiar la pol.","Proiecția cilindrică.","Proiecția conică.","Proiecția Robinson."]','Gândește-te ce proiecție „atinge" globul tocmai în dreptul polului. Proiecția azimutală, cu planul tangent la pol, redă cel mai fidel zonele polare, unde proiecția cilindrică deformează enorm.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('3760c03c-dead-4e7c-8636-835dd9d5dde8','9','geografie-fizica','published',3,84,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('3760c03c-dead-4e7c-8636-835dd9d5dde8','ro','Pentru harta unui continent aflat la latitudini medii în emisfera nordică (de exemplu Europa), care proiecție redă cel mai fidel realitatea?','["Proiecția azimutală.","Proiecția cilindrică.","Proiecția Robinson.","Proiecția conică."]','Fiecare proiecție este fidelă acolo unde suprafața de proiecție „atinge" globul. Conul se sprijină pe latitudinile medii, așa că proiecția conică redă cel mai bine regiunile din emisfera nordică, precum Europa.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('459649e0-0f98-41c8-a606-b97b87dd2f65','9','geografie-fizica','published',1,85,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('459649e0-0f98-41c8-a606-b97b87dd2f65','ro','Un elev vrea o proiecție care să păstreze în același timp, perfect, și suprafețele, și distanțele, și unghiurile. De ce nu este posibil?','["Pentru că nu există hărți suficient de mari.","Pentru că nicio proiecție nu le poate păstra pe toate deodată — cel puțin una dintre proprietăți se deformează mereu.","Pentru că scara ar deveni prea mare.","Pentru că ar fi nevoie de prea multe semne convenționale."]','Reține că trecerea de la curb la plan cere mereu un „preț". Poți alege ce proprietate păstrezi (suprafețe, distanțe sau unghiuri), dar nu pe toate simultan — o proiecție care le-ar păstra pe toate nu există.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a81c4148-bd66-4904-86a5-db6f6c37c794','9','geografie-fizica','published',2,86,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a81c4148-bd66-4904-86a5-db6f6c37c794','ro','La navigație se folosesc proiecții care păstrează corect unghiurile (forma). De ce este acest lucru important pe mare?','["Pentru că arată corect suprafața oceanelor.","Pentru că micșorează distanțele reale.","Pentru că permit trasarea și menținerea corectă a direcției de mers.","Pentru că elimină complet orice deformare de pe hartă."]','Gândește-te ce îi trebuie cel mai mult unui navigator: să știe încotro să meargă. Dacă unghiurile sunt păstrate corect, direcția trasată pe hartă corespunde direcției reale, deci nava poate ține drumul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('50f594f6-ecac-493a-ac24-08160c843dc1','9','geografie-fizica','published',0,87,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('50f594f6-ecac-493a-ac24-08160c843dc1','ro','Vrei să compari corect întinderea (suprafața) a două țări folosind o hartă. Ce tip de proiecție îți trebuie?','["O proiecție echivalentă, care păstrează corect suprafețele.","O proiecție care păstrează corect unghiurile.","Orice proiecție, fiindcă rezultatul este mereu același.","O proiecție care mărește suprafețele spre poli."]','Dacă te interesează cât de mari sunt teritoriile, ai nevoie de o hartă care nu falsifică ariile. Proiecția echivalentă păstrează corect raportul dintre suprafețe, deci comparația este validă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e72cf0be-6291-439a-bf59-62453a60fdf5','9','geografie-fizica','published',3,88,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e72cf0be-6291-439a-bf59-62453a60fdf5','ro','Care hartă are scara mai mare și arată mai multe detalii: una la 1 : 20 000 sau una la 1 : 2 000 000?','["Cea la 1 : 2 000 000, pentru că numărul este mai mare.","Au exact aceeași scară.","Nu se pot compara, fiind scări diferite.","Cea la 1 : 20 000, pentru că numărul de la numitor este mai mic."]','Scara este o fracție: cu cât numitorul e mai mic, cu atât fracția (scara) e mai mare. La 1 : 20 000 numitorul e mult mai mic, deci scara e mai mare, teritoriul mai mic și detaliile mai multe.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('44f84344-3b4a-4c8f-9f60-6a121d790c63','9','geografie-fizica','published',1,89,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('44f84344-3b4a-4c8f-9f60-6a121d790c63','ro','Pe o hartă la scara 1 : 100 000, un segment de 1 cm măsurat pe hartă corespunde în realitate la:','["100 m.","1 km.","10 km.","100 km."]','Înmulțește lungimea de pe hartă cu numărul scării. 1 cm × 100 000 = 100 000 cm = 1000 m = 1 km.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e4d280d3-17b6-4a1e-8629-1864ac538f65','9','geografie-fizica','published',2,90,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e4d280d3-17b6-4a1e-8629-1864ac538f65','ro','Un coleg notează poziția unui oraș ca fiind „45° latitudine estică". Unde greșește?','["Latitudinea nu se măsoară deloc în grade.","Latitudinea poate ajunge până la 180°.","Latitudinea este nordică (N) sau sudică (S), nu estică — „estică” se referă la longitudine.","Latitudinea se măsoară pornind de la poli, nu de la Ecuator."]','Desparte clar cele două coordonate: una merge N–S, cealaltă E–V. Latitudinea (0° la Ecuator, până la 90° la poli) este nordică sau sudică; est și vest sunt sensuri ale longitudinii.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('dc363c23-1686-418a-8efa-3ddf7ef0779c','9','geografie-fizica','published',0,91,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('dc363c23-1686-418a-8efa-3ddf7ef0779c','ro','Între ce valori poate fi longitudinea unui punct și față de ce reper se măsoară?','["Între 0° (meridianul de origine, Greenwich) și 180° (antemeridian).","Între 0° (Ecuator) și 90° (poli).","Între 0° și 360°, măsurată față de poli.","Între 0° și 90°, măsurată față de antemeridian."]','Longitudinea se numără pe meridiane, plecând de la meridianul de origine. Ea crește de la 0° (Greenwich) până la 180° (antemeridian), spre est sau spre vest.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ac1a25ae-64f9-459f-ac36-52c09a9f9f47','9','geografie-fizica','published',1,92,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ac1a25ae-64f9-459f-ac36-52c09a9f9f47','ro','De ce o hartă la scară mică (de exemplu a unui continent întreg) nu poate arăta fiecare stradă sau fiecare pârâu?','["Pentru că astfel de hărți sunt întotdeauna vechi.","Pentru că, prin micșorarea puternică, harta este generalizată și detaliile mărunte se pierd.","Pentru că nu are legendă.","Pentru că folosește obligatoriu proiecția conică."]','O suprafață uriașă strânsă pe o singură foaie nu are loc pentru toate amănuntele. La scară mică, harta este generalizată: se păstrează doar ce este important, iar detaliile mici dispar.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6a5f4f51-de56-421c-9203-e28751dde91f','9','geografie-fizica','published',2,93,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6a5f4f51-de56-421c-9203-e28751dde91f','ro','De ce nu poți „citi" corect o hartă necunoscută dacă îi lipsește legenda?','["Pentru că nu ai cum să afli titlul hărții.","Pentru că nu poți calcula scara.","Pentru că legenda explică semnele convenționale prin care sunt reprezentate obiectele de pe hartă.","Pentru că legenda este cea care indică direcția nordului."]','Semnele de pe hartă sunt convenționale — nu au sens de la sine. Legenda este „dicționarul" care le traduce, așa că fără ea nu știi ce reprezintă fiecare simbol.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b361034a-9200-4412-b849-8c61f7913f14','9','geografie-fizica','published',3,94,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b361034a-9200-4412-b849-8c61f7913f14','ro','De ce două curbe de nivel nu se pot intersecta niciodată?','["Pentru că sunt desenate cu aceeași culoare.","Pentru că ar ocupa prea mult loc pe hartă.","Pentru că ar strica scara hărții.","Pentru că, în punctul de intersecție, terenul ar trebui să aibă în același timp două altitudini diferite, ceea ce este imposibil."]','Reține că fiecare curbă înseamnă o singură altitudine. Dacă două curbe s-ar întâlni, punctul comun ar avea simultan două înălțimi diferite — o imposibilitate fizică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9328077b-1ead-48c5-9bcc-e6da456349a9','9','geografie-fizica','published',0,95,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9328077b-1ead-48c5-9bcc-e6da456349a9','ro','Pe o hartă topografică, valoarea curbelor de nivel crește spre interiorul lor. Ce formă de relief indică acest lucru?','["O formă pozitivă (un deal sau un munte).","O depresiune adâncă.","O suprafață perfect plană.","Un lac de mare adâncime."]','Dacă altitudinile cresc pe măsură ce mergi spre centru, terenul urcă spre interior. Aceasta înseamnă o formă pozitivă, adică o înălțime (deal sau munte).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('21174803-b2b8-4818-b630-662765dfb246','9','geografie-fizica','published',1,96,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('21174803-b2b8-4818-b630-662765dfb246','ro','Într-o zonă de pe harta topografică, valoarea curbelor de nivel scade spre interior. Ce reprezintă cel mai probabil?','["Un vârf de munte.","O formă negativă (o depresiune sau o vale).","O câmpie perfect plană.","Un platou înalt."]','Dacă altitudinile scad spre centru, terenul coboară spre interior. Este semnul unei forme negative — o adâncitură, cum ar fi o depresiune sau o vale.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e5d6fec2-a45e-400b-8478-cdb444458813','9','geografie-fizica','published',2,97,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e5d6fec2-a45e-400b-8478-cdb444458813','ro','Pe o hartă topografică, într-o porțiune curbele de nivel sunt foarte dese, iar în alta foarte rare. Ce putem deduce despre teren?','["Porțiunea cu curbe rare are panta cea mai abruptă.","Curbele dese arată o suprafață perfect plană.","Porțiunea cu curbe dese are panta mai abruptă, iar cea cu curbe rare — pantă mai lină.","Densitatea curbelor nu are nicio legătură cu panta."]','Curbe apropiate înseamnă că altitudinea se schimbă mult pe o distanță mică — adică urci repede. Deci curbele dese arată o pantă abruptă, iar cele rare o pantă lină.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d2872006-9286-4659-ad7f-57c8134ec704','9','geografie-fizica','published',1,98,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d2872006-9286-4659-ad7f-57c8134ec704','ro','Ce reprezintă „echidistanța" pe o hartă topografică?','["Distanța pe orizontală dintre două localități vecine.","Diferența de altitudine (pe verticală) dintre două curbe de nivel succesive.","Lungimea totală a unei curbe de nivel.","Numărul de curbe principale de pe hartă."]','Cuvântul se referă la înălțime, nu la distanța pe hartă. Echidistanța este saltul de altitudine (constant) de la o curbă de nivel la următoarea.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fe299a78-69d2-45d5-ab47-b186bd7161b9','9','geografie-fizica','published',0,99,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fe299a78-69d2-45d5-ab47-b186bd7161b9','ro','O regiune se află la altitudini cuprinse între 0 și 200 m. Cărei trepte de relief îi aparține?','["Treapta câmpiilor.","Treapta dealurilor.","Treapta munților.","Treapta podișurilor înalte."]','Compară intervalul dat cu treptele de relief după altitudine. Intervalul 0–200 m corespunde treptei celei mai joase, adică treapta câmpiilor.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('54c96ecd-fb05-49ed-947f-0c48992d195d','9','geografie-fizica','published',3,100,1783200000000,1783200000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('54c96ecd-fb05-49ed-947f-0c48992d195d','ro','Un turist rătăcit vrea să afle exact unde se găsește (coordonate, altitudine) și încotro se deplasează. Ce tehnologie îl ajută cel mai direct?','["GIS-ul, prin straturile lui de date.","Teledetecția, prin imagini satelitare.","Curbele de nivel de pe o hartă topografică.","GPS-ul (sistemul de poziționare globală)."]','Caută tehnologia gândită tocmai pentru a spune „unde ești" în timp real. GPS-ul furnizează direct coordonatele, altitudinea, direcția și viteza celui care îl folosește.');
